/*
 * Authenticate the caller and compose both messages.
 *
 * This workflow can send a real SMS and a real email to whatever it is
 * handed, so the key check is the only thing between the portal's OTP
 * channel and an open relay. It runs first and fails closed.
 */
const crypto = require('crypto');
const KEY = '__OTP_API_KEY__';

const item = $input.first().json;
const hdr = item.headers || {};
const b = item.body || {};

// Compare digests rather than strings: timingSafeEqual throws on a length
// mismatch, and that throw would itself leak how long the secret is.
const given = crypto.createHash('sha256').update(String(hdr['x-api-key'] || '')).digest();
const want = crypto.createHash('sha256').update(KEY).digest();
if (!crypto.timingSafeEqual(given, want)) {
  return [{ json: { ok: false, error: 'Not authorised.' } }];
}

// Indian mobile, in E.164. Anything else is refused rather than dialled.
const e164 = String(b.e164 || '').trim();
if (!/^\+91[6-9][0-9]{9}$/.test(e164)) {
  return [{ json: { ok: false, error: 'A valid +91 mobile number is required.' } }];
}

// Six digits and nothing else. Both templates drop this in verbatim, so
// anything that is not a code has no business reaching them.
const code = String(b.code || '');
if (!/^[0-9]{6}$/.test(code)) {
  return [{ json: { ok: false, error: 'A six-digit code is required.' } }];
}

const email = String(b.email || '').trim().toLowerCase();
const validEmail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) ? email : '';

const minutes = Math.max(1, Math.round(Number(b.ttlSeconds || 300) / 60));
const plural = minutes === 1 ? '' : 's';

return [{
  json: {
    ok: true,
    phone_e164: e164,
    email: validEmail,
    code,
    sms: `${code} is your MHA Samadhan verification code. It expires in ${minutes} minute${plural}. Do not share it with anyone.`,
    subject: `${code} is your MHA Samadhan verification code`,
    intro: 'Use this code to sign in to MHA Samadhan, the Ministry of Home Affairs grievance portal.',
    note: `This code expires in ${minutes} minute${plural}.`,
    warn: 'If you did not request this, you can ignore this email. Nobody can access your grievances without the code.',
  },
}];
